INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter30-mulki-movement', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter30-mulki-movement-p1", "partName": "Mulki and its Origins in the Bahmani Period", "bodyMd": "The word **mulk** means country or motherland, and a **mulki** is a native of that country. **Gair-mulki** (or non-mulki) refers to a foreigner or outsider. In the Deccan, mulkis were also understood as **swadeshis** (natives of the land), while non-mulkis were outsiders who came in and settled.\n\nThe mulki–non-mulki problem traces back to the Bahmani period.\n\n*   After the decline of the Kakatiyas, the Bahmanis ruled the Deccan.\n*   During the 14th century, the armies of the Khilji and Tughlaq clans of the Delhi Sultanate, along with many Muslims, migrated to the Deccan and settled there.\n*   These settlers came to be called **deccanies**.\n\nAround the same time, Muslims from West Asian countries — Iran, Iraq, Arabia, and Turkey — also came to India and settled in the Bahmani empire.\n\n*   They were called **Aphakis** (Afaqis), meaning non-local or foreigner.\n*   Over time, deccanies came to be regarded as mulkis, and aphakis as non-mulkis.\n\n**Conflict under the Bahmanis:**\n\n*   **Ahmed Shah**, the third Bahmani king, appointed **Mohammed Gavan**, an aphaki, as prime minister. Gavan carried out major administrative reforms and appointed fellow aphakis to prominent posts.\n*   Aphakis came to dominate trade and grew financially and socially powerful, also being hired into high state positions.\n*   This created conflict between the deccanies (mulkis) and aphakis (non-mulkis).\n*   Religious sectarian difference deepened the conflict: aphakis belonged to the **Shia** sect and deccanies to the **Sunni** sect of Islam.\n*   At Bidar, the Bahmani capital, deccani nobles had the 78-year-old prime minister **Khwaja Mahmud Gavan** assassinated on suspicion of treachery; his killing left the Bahmani kingdom shattered.\n*   The aphaki–deccani rivalry intensified until it culminated in the downfall of the Bahmani empire in 1527, which broke up into five successor kingdoms — one of which was the Qutub Shahi kingdom of Golconda.", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter30-mulki-movement-p2", "partName": "Qutub Shahi Period — No Mulki Issue", "bodyMd": "The Qutub Shahi dynasty emerged from the Bahmani breakup. **Quli Qutub Shah**, its founder, was himself an aphaki (an immigrant from Iran). Having witnessed the Bahmani collapse caused by aphaki–deccani rivalry, he deliberately offered more jobs to deccanies (mulkis) and encouraged the local language, **Telugu**.\n\nFrom the late 14th century to the late 17th century, Golconda was the capital from which the Qutub Shahis ruled greater Andhra.\n\n*   **Miir Jumla** installed **Madanna** as prime minister in 1674.\n    \n*   He was succeeded by **Abul Hasan Tanisha**, who honoured him with the title **Suryaprakasarao**.\n    \n*   This was the first time in 300 years since Allauddin Khilji''s invasions that a Hindu had been made prime minister.\n    \n*   Madanna''s brother, **Akkanna**, was made revenue minister.\n    \n*   **Abul Hassan Tanisha** appointed Telugu people to important positions: **Akkanna** as peshkar and **Madanna** as mahamantri (prime minister).\n    \n*   Because the Qutub Shahis respected the local language and culture and hired locals extensively, the mulki issue did not arise during this period.\n    \n*   Mulki–non-mulki rivalry eventually caused Madanna''s assassination, which in turn shook the foundations of the Qutub Shahi kingdom.", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter30-mulki-movement-p3", "partName": "Asaf Jahi Period — Emergence and Escalation of the Mulki Problem", "bodyMd": "In 1724, **Nizam-ul-Mulk** founded the Asaf Jahi dynasty at Hyderabad. He brought with him loyal followers, whom he made ministers and appointed to noble posts; their descendants settled permanently in the Deccan.\n\n*   The first Nizam brought with him trusted Muslims and Urdu-speaking Kayasthas, granting them large positions.\n*   Among these arrivals, **Abul Hasan Sher Khan** rose to become Nawab.\n*   Under later Nizams, **saranjams** (assignments) went to families such as **Mir Alam**, **Chandulal**, and **Imadul Mulk** — all originally outsiders.\n*   Before India''s independence, large parts of the Nizam''s territory — Karnataka, Uttar Sarkars, Rayalaseema, and Berar — were merged into British territory.\n*   Muslim officials serving in the erstwhile courts of Delhi, Murshidabad, and Lucknow, whose kingdoms had fallen, were dismissed by the British as \"disloyal\" once those regions came under British rule.\n*   Many of them moved to Hyderabad, treating the Nizam as heir to the Mughal emperor.\n*   They took up occupations such as medicine, contracting, and trade, and secured government jobs.\n*   Society under the Nizam''s **jagirdari system** was deeply layered: education was largely limited to the upper classes, who were reluctant to take up employment.\n*   Some who came seeking work chose to settle permanently in Hyderabad.\n*   Administration required staffing district offices, so people were specifically summoned and given jobs, while jagirdars themselves lived lives of leisure.\n*   Outsiders from beyond the state''s borders performed the harder administrative duties.\n*   This coexistence, ideally, ran without regard to religion or language acting as unifying strength — but mulki grievances were never fully resolved.\n*   The mulki problem intensified only from the time of **Afzal-ud-Daulah**, the fifth Nizam, marking the start of organised mulki movements.\n\nThe Asaf Jahi-era mulki–non-mulki conflict is studied in three phases.\n\n### Phase 1 (1853–1883): Salarjung-I\n\n**Background — a dispute of succession triggers the first rift:**\n\n*   Under the fifth Nizam, **Afzal-ud-Daulah**, and his prime minister **Salarjung-I**, disagreement arose over a key appointment.\n*   The Nizam wanted a particular person appointed, but Salarjung would not accept him; Salarjung, aggrieved, was ready to resign.\n*   The British, seeing Salarjung''s rising influence, were not entirely happy but could not risk removing him.\n*   When Salarjung appeared ready to resign, the Nizam was privately relieved that a long-standing matter might resolve itself.\n*   But Salarjung''s resignation was unwelcome to his own body of followers — in reality, all real power lay in his hands, and his supporters feared for their own positions if he left, so they worked out a plan together.\n*   The Nizam had a private weakness for fakirs and often acted on their advice.\n*   His followers bribed a fakir close to the Nizam to speak in Salarjung''s favour.\n*   When the Nizam raised the matter before this fakir, the fakir praised Salarjung as a good man and urged the Nizam to reinstate him at once — and the plan worked.\n*   The man Salarjung had originally proposed got the post, Salarjung''s authority remained unchallenged, and the Nizam himself grew more attached to Salarjung as a result.\n*   From this point on, sympathies split between followers loyal to the Nizam and followers loyal to Salarjung, and the mulki–non-mulki conflict began in earnest.\n\n**Reforms and migration into Hyderabad:**\n\n*   In 1853, **Salarjung-I** was appointed Diwan of Hyderabad and carried out extensive administrative and revenue reforms.\n*   These reforms drew **Kayasthas** and **Khatris** from North India to Hyderabad in search of jobs.\n*   **Sayyed Ahmed Khan** and **Aminuddin Khan**, Salarjung''s assistants, played a key role in facilitating the arrival of non-mulkis.\n*   English-knowing personnel were brought in from Madras Presidency for administrative work and given respectable posts.\n*   After the **collapse of the Mughal empire** following the **1857 Sepoy Mutiny**, many who lost jobs in North India migrated to Hyderabad in search of employment.\n*   Though Salarjung himself was reluctant to employ non-mulkis, certain unavoidable circumstances forced him to appoint educated men from **Aligarh University**.\n*   Officers trained and experienced in British India were hired as Diwanis.\n*   Salarjung''s original expectation — that skilled outside employees would train locals and then return home — did not materialise.\n*   Non-mulkis in high positions unnecessarily split their departments to create new posts, filling them with friends and relatives brought from North India.\n*   This bred growing resentment of gair-mulkis (non-mulkis) among the mulki population.\n\n**Salarjung''s countermeasures:** Fearing that a rising non-mulki population would affect Deccan''s culture and politics, Salarjung took several measures:\n\n*   Non-mulki officers required special permission to meet the Nizam''s family, the Diwan, the British Resident, or other nawabs.\n*   Non-mulki officers could not be granted titles or jagirs.\n*   Non-mulkis were kept out of army recruitment to prevent their domination of the armed forces.\n*   He rejected the proposal to replace Persian with Urdu as the official language.\n*   He famously told pressuring North Indian Muslim officials that Persian was a symbol of Islam''s historic triumph, and that as long as he lived, Persian would live on in Hyderabad even if it had died out elsewhere.\n*   Salarjung would remark that though non-mulkis might be skilled, they could not claim the same status as locals who had been loyal to the Nizam for generations.\n\n**First Mulki Orders (1868):** With the aim of educating mulkis and securing them government jobs, Salarjung-I issued the first-ever order in **1868** confining employment in all administrative offices of Hyderabad to mulkis, during the reign of the fifth Nizam, Afzal-ud-Daulah.\n\n### Phase 2 (1884–1911): Peak Conflict under Mir Mahboob Ali Khan\n\nThe mulki–non-mulki conflict reached its peak during the reign of the sixth Nizam, **Mir Mahboob Ali Khan**.\n\n*   Salarjung-I died in **1883**; **Salarjung-II** became Diwan and was biased in favour of non-mulkis.\n*   Under pressure from non-mulkis, Salarjung-II replaced **Persian** with **Urdu** as the official language on **21 February 1884**.\n*   He also made **English** compulsory, driven by British interests.\n*   Making Urdu official and English compulsory reduced job opportunities for mulkis, who were not proficient in either language.\n*   Non-mulkis were also paid higher salaries than mulkis, and mulkis came to be treated as second-class citizens.\n*   Mulkis submitted a memorandum to Mahboob Ali Khan alleging Salarjung-II''s bias, known as the **\"Mulki Paper.\"**\n*   The Nizam responded by ordering that a list of employees be prepared based on their nativity.\n\n**Employees'' Civil List, 1886:**\n\n| Birthplace | Employees | Percentage | Salary Share |\n|---|---|---|---|\n| Hyderabad State | 246 | 52% | 42% |\n| British India (total) | 230 | 48% | 58% |\n\nBreakdown of the 230 employees recruited from British India:\n\n| Source Region | Employees | Percentage | Salary Share |\n|---|---|---|---|\n| Madras & Bombay presidencies (excl. below) | 97 | 20% | 24% |\n| Madras Presidency | 66 | 14% | 11% |\n| Bombay Presidency | 36 | 8% | 8% |\n| Other European countries | 24 | 5% | 13% |\n| **Total (non-mulki)** | **230** | **48%** | **58%** |\n\nWhile mulkis formed the majority of employees, their salary share (42%) fell well short of their numbers (52%). Non-mulkis held nearly half the jobs yet drew a disproportionately larger share of pay — and this report escalated the mulki movement further.\n\n**1888 Gazette (Jarida):** To control the growing movement, Mahboob Ali Khan issued a gazette in **1888** (dated 15 Rabi-ul-Sani, 1301 AH per the Islamic calendar). Key provisions:\n\n1.  This gazette used the word **\"mulki\"** for the first time in an official document.\n2.  Persons who had resided in the state for at least **12 years** were to be considered mulkis.\n3.  All posts were to be filled with citizens of the state based on merit, without interference from foreigners.\n4.  Non-mulkis required special permission from the prime minister to obtain a job.\n\nEven after the gazette''s release, the hiring of non-mulkis continued to rise, and enforcement remained weak. Mulki certificates were not easy to obtain regardless of language spoken, and most certificate-holders among employees were, in practice, mulki by category.\n\n**Hindu–Muslim dimension:** Though Hindus formed **90%** of the population, most jobs went to non-mulki Muslims, who made up only about **10%** of the state''s population — a disparity that fed Hindu–Muslim tensions on top of the mulki–non-mulki divide.\n\n**Employees'' Civil List, 1894:** Salarjung-II, disregarding the Nizam''s instructions, continued favouring non-mulkis, further escalating the movement. He resigned as Diwan in **April 1887**, and under the new Diwan, a fresh civil list was released in 1894:\n\n| Category | Employees |\n|---|---|\n| Total gazetted employees | 680 |\n| Mulki employees | 233 |\n| Non-mulki employees | 447 |\n\n*   Non-mulkis thus made up roughly **67%** of higher officials, and their administrative influence grew correspondingly.\n*   Of the 680 total employees, only **63** were Hindus, and among those, only **20** were mulki Hindus.\n*   Non-mulki numbers had risen sharply — from 230 in the 1886 list to 447 by 1894.\n\n**Maharaja Kishan Parshad and mulki protection (1901–1911):**\n\n*   In **1901**, **Maharaja Sir Kishan Parshad**, a Hindu mulki, was appointed Diwan. He sided with the mulkis and worked to curb non-mulki dominance.\n*   His finance minister, **Kaasan Walker**, nonetheless hired many non-mulkis.\n*   Walker also divided Urdu into \"Northern Urdu\" and \"Southern Urdu,\" disparaging mulkis as speakers of an \"uncivilised\" Southern Urdu against a \"civilised\" Northern Urdu spoken by non-mulkis — provoking direct conflict between Kishan Parshad and Walker.\n*   Because of Kishan Parshad''s efforts, the mulki movement achieved partial success.\n*   In **1910**, the government issued a notification protecting mulkis: non-mulki jobs were to be treated as temporary, recruitment was to be by written examination rather than political influence, and locals with sufficient qualifications were to be preferred over non-locals.\n*   Kishan Parshad is remembered as the **\"godfather of the mulki movement.\"**\n\n**The press and the mulki debate:** Contemporary journals actively debated the issue:\n\n*   **Hyderabad Recorder** published news favouring mulki rights.\n*   **Ilahibaksh**, a pro-non-mulki magazine, mockingly asked \"where we find a clever mulki who can administer Hyderabad.\"\n*   **The Mohammadin**, also pro-non-mulki, argued that non-mulkis were descendants of people originally invited by Salarjung.\n*   In **1912**, **Mir Osman Ali Khan** removed Kaasan Walker from his post as finance minister.\n\n**Rai Balamukund:** In 1885, **Rai Balamukund**, a Khatri student from Hyderabad''s' WHERE chapter_slug = 'telangana-history-en-chapter30-mulki-movement';
UPDATE theory_content SET concepts_json = concepts_json || ' old city, graduated with a B.A. from Madras University — the first Hindu mulki graduate in Hyderabad state. In **1908**, he was appointed Chief Justice of the Hyderabad High Court (established in 1890).\n\n### Phase 3 (1911–1948): Mir Osman Ali Khan and the Definition of Mulki\n\nAfter Mir Mahboob Ali Khan''s death in 1911, **Mir Osman Ali Khan**, the seventh Nizam, came to power.\n\n**Osmania University and the language divide:**\n\n*   On the recommendation of an educational conference, Osman Ali Khan established **Osmania University in 1918**, with **Urdu** as the medium of instruction.\n*   However, the university''s Urdu translation department was staffed largely by non-mulki officers from North India.\n*   They used **Lakhnavi (Lucknow) Urdu** in textbooks instead of the **Deccani Urdu** spoken locally, creating a fresh language-based divide: mulkis used Deccani Urdu, non-mulkis used Lakhnavi Urdu.\n*   Osmania University produced educated citizens but was less successful at producing government officers.\n*   **Nizam College**, which taught in English, produced most government officers instead.\n*   Mulki children largely attended Osmania University while non-mulki children attended Nizam College — deepening academic and career differences between the two groups.\n*   Separately, once Osmania University began instruction in Urdu, education gained a degree of freedom from earlier restriction, and the poor and common people gained access to schooling.\n*   Yet without matching economic capacity, many educated but under-resourced young men still could not attain proportionate opportunity.\n*   Jagirdars — regardless of qualification — continued to occupy top posts by virtue of status, and even ordinary Muslims suffered under this feudal arrangement.\n*   The resulting unrest is treated as the fourth phase of the mulki movement''s discontent, originating in the same underlying inequality.\n*   Government translation of Urdu land records into other languages later caused large-scale fraud in land rights, and many original land records were altogether destroyed.\n\n**Ideological currents — Deccan Nationalism vs. Muslim Sovereignty:**\n\n*   **Deccan Nationalism** was proposed by Osmania University''s Urdu professor **Dr. Jorey**; other OU professors joined him in protecting mulkis and Deccani Urdu.\n*   The **Idara-e-Adabiyat-e-Urdu** library, started by OU''s mulki professors in **1930**, published articles on Deccan Nationalism.\n*   This library played a key role in uniting mulkis across caste and religious lines.\n*   Deccan Nationalist leaders raised the slogan **\"Long live Nizam, the royal embodiment of Deccan Nationalism.\"**\n*   **Muslim Sovereignty** emerged in opposition to Deccan Nationalism, initially supported only by non-mulkis.\n*   It later split mulkis along Hindu–Muslim lines, drawing support even from mulki Muslims and thereby weakening the mulki movement.\n*   This theory was later widely invoked by the **Razakars**.\n\n**The 1919 Farman — Definition of Mulki:** To protect mulki rights, Mir Osman Ali Khan issued a Farman in 1919, known as the **Mulki Rules**. Key provisions:\n\n1.  Only mulkis were to be appointed to government jobs. A person qualified as mulki if any one condition was met: (a) born in Hyderabad state; (b) resident of Hyderabad; (c) father completed 15 years as a government employee by the child''s birth; (d) for a woman, being the wife of a mulki.\n2.  A person whose father was a mulki at the time of their birth is considered mulki.\n3.  A person completing **15 years** of permanent residence in Hyderabad state is considered mulki, provided they submit a magistrate-attested affidavit stating they will not return to their former place.\n4.  A mulki woman who marries a non-mulki but continues residing in Hyderabad retains her mulki status and rights.\n5.  A mulki woman living outside the state after marrying a non-mulki, who returns as a permanent resident after his death or divorce, is considered mulki — though her children do not automatically inherit mulki status unless they independently satisfy the rules.\n6.  **Talukdars** were authorised to issue Mulki Certificates under these rules.\n7.  Applicants for a mulki certificate had to furnish full personal details and attest to their accuracy, with liability for punishment under Provision 9 for false information.\n8.  A rejected application could be resubmitted within a month to the **Subedar**, whose decision was final.\n9.  A certificate could be cancelled if the holder was later found to have furnished false information, upon recognition by the government or police.\n\n*   Under Provisions 1(a)–(c), a person disobedient to the Hyderabad state, or one who participated in activities against state politics or worked against government interests, would forfeit their mulki rights.\n*   All non-mulki jobs were treated as temporary.\n*   All government jobs were to be filled through written examinations, not political appointment; some fairness was extended to mulkis in promotions.\n*   The Farman also established the **Civil Services Executive Council**, an independent body for selecting employees.\n*   In **1938**, this council appointed a committee to study civil services.\n*   Based on its report, a Farman issued on **27 April 1947** created the **Hyderabad Public Service Commission**, comprising a chairman and four members appointed by the Nizam on the executive council chairman''s recommendation.\n\n**Mulki organisations of the 1920s–30s:**\n\n*   **Osmania Graduates Association (1920)** — a mulki political organisation formed in Hyderabad; it still operates several educational institutions in Telangana today and also established an exhibition society.\n*   **Hyderabad State Reforms Organisation (1921)** — formed by educated Hyderabadis to pursue constitutional reforms.\n*   **Society of Union and Progress (1926)** — formed in London by Hyderabadi students studying there, to promote the establishment of a responsible government.\n*   **Hyderabad Association (1930)** — started under **Barrister Kishan**, demanding a responsible government and administrative reforms.\n\n**1933 Farman:**\n\n*   In 1930, Khan Sahebs from Punjab were directly appointed to senior posts in Hyderabad, affecting the promotion prospects of local employees and reigniting the mulki–non-mulki dispute.\n*   To ease discontent, Mir Osman Ali Khan issued a Farman in **1933** giving priority to educated, efficient mulkis in recruitment and confining non-mulki appointments to a temporary basis.\n*   **Hyderabad Kotwal Raja Venkatarami Reddy** supported mulki activists throughout.\n*   Mulki activists and the public held a meeting to thank the Nizam for this Farman; attendees included **Kumari Padmaja Naidu**, **Mandamula Narsingarao**, **Burgula Ramakrishna Rao**, **Mir Akbar Ali Khan**, **Dr. Lateef Sayyid**, **Raja Dhonderaj**, and **Nawaz Shamsheer Jung**.\n\n**Nizam Subjects League, 1935 (Nizam Mulki League):**\n\n*   Formed by mulki activists in 1935; called **Jamiath Rifayame Nizam** in Urdu and **Nizam Prajala Sangham** in Telugu.\n*   Slogan: **\"Hyderabad for Hyderabadis.\"**\n*   **President:** Nawab Sir Nizamat Jung (who also served as political minister in the Nizam''s council of ministers).\n*   **Vice-Presidents:** Dr. Lateef Sayyid and Ramachandra Nayak.\n*   **Treasurer:** Barrister Noushid Chinay.\n*   **Secretaries:** Sayyid Abid Hassan, Boorgula Ramakrishna Rao, and Srinivas Sharma.\n*   **Executive committee** (18 members) included Raja Bahadur Venkataramireddy, Vaman Nayak, Nawab Bahadur Yarjung, Kashinathrao Vaidya, Akbar Alikhan, Mandamula Narsingrao, and Mir Hassanoddin (editor of the _Mamlakath_ newspaper), among others.\n\n**Significance of the Nizam Mulki League:**\n\n*   Protected mulki rights while remaining loyal to the Nizam and preserving the local language.\n*   Respected and promoted local culture and traditions.\n*   Promoted unity across social sections while supporting the development of downtrodden groups.\n*   Pushed for government accountability to an elected legislature, aiming for a parliamentary, responsible government.\n*   Declared loyalty to the Nizam while framing its movement as protection of Deccan culture and language, and worked to safeguard the Nizam state''s royal rights.\n*   Under pressure from the League, the government formed a committee under **Aravamudam Iyengar**, whose recommendations led to amendments strengthening the Mulki Rules in **1939**.\n*   The Nizam initially supported the League''s goals, but its demand for a Responsible Government angered him, which cooled public enthusiasm for the League.\n*   Some Muslim intellectuals influenced by the Muslim Sovereignty ideology left to join **Ittehadul Muslimin**, and the Nizam Subjects League was dissolved in **1939**.\n\n**Formation of the People''s Convention (1937):** A split within the Mulki League saw Hindu members leave and form the **People''s Convention**. (Note: League leader Sayyid Abid Hassan authored a book titled _Whither Hyderabad_.)\n\n**Aravamudam Iyengar Committee (1937–38):** Appointed by the Nizam''s government in 1937 for political reforms, it submitted its report in 1938, recommending:\n\n*   Job appointments should strictly follow the Mulki Rules.\n*   Acting on the committee''s recommendations, the definition of mulki was made more stringent under **Article 39 in 1945**.\n*   Candidates for government jobs should be judged on efficiency, skill, and moral conduct, without partiality.\n*   A dedicated system should be established for government employee appointments.", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter30-mulki-movement-p4", "partName": "Violation of Mulki Rules, 1948–52: Military Rule and the Vellodi Government", "bodyMd": "Between **1948 and 1952**, Hyderabad state was merged into the Indian federal system and faced considerable social, economic, and political upheaval. The government recognised the need to build public confidence in the new administration through law and order and economic stability, introducing several new employment measures:\n\n*   **Police recruitment:** Under the Nizam, over 90% of civil jobs had been held by a single social class, prompting the new government to broaden participation, especially in the armed forces.\n    *   It resolved that, by **1 January 1954**, **60%** of posts would be filled by other social categories.\n    *   Armed forces personnel from Madras, the Central Provinces, and Bombay were appointed to maintain peace and security.\n*   **Language policy:** Priority was given to Telugu in administration, since most people in Hyderabad state were Telugu speakers, and Telugu-proficient people were preferred for jobs over those favouring Urdu.\n*   **Land reform:** The government decided to abolish the **Jagirdari System** and bring land management under the revenue department, creating a new job category for this purpose.\n*   **Central deputation:** To stabilise the economy and normalise conditions, the Vellodi government brought in **over 200 officials of the Indian Union**.\n*   **Anti-corruption measures:** Employees who had engaged in politics, corruption, or misuse of office under the Nizam were removed.\n    *   The new government appointed **M. A. Rahman** as Public Service Commission officer post-independence, creating fresh openings.\n    *   Military officer **Chowdary** personally reviewed several such cases.\n*   **Military and police reforms:** The Hyderabad Army, numbering **17,870** at the time of Police Action, was reduced to **10,415**, on the assessment that such a large force was unnecessary.\n    *   Police staff appointed during Police Action were later also reduced, with appointments based on district-level need and priority extended to non-Muslims as well.\n*   **Rehabilitation:** Personnel who had resigned from the army after the Second World War were given new jobs through the **Directorate of Rehabilitation**, which continued functioning for a time even after Hyderabad''s merger with the Indian Union.\n*   **Employment exchanges** were set up in **Hyderabad, Warangal, and Aurangabad** to fill lower- and mid-level government posts and place candidates in private-sector jobs within government departments.\n*   The **Bikaner Training Institute** was established to expand opportunities for skilled and technical labour, training around **1,200 people annually across 20 different fields**.\n\n**Operation Polo and its aftermath:**\n\n*   On **17 September 1948**, **Operation Polo** (Police Action) ended Nizam rule in Hyderabad, merging the state with the Indian Union.\n*   **J. N. Chaudhuri** (from Bengal) served as Military Governor of Hyderabad from **September 1948 to December 1949**.\n*   **M. K. Vellodi** (from Kerala) served as the state''s Chief Minister from **January 1950 to March 1952**.\n*   Since both Chaudhuri and Vellodi were non-locals, the inflow of outsiders into Hyderabad''s administration continued.\n*   In the name of modernising the regime, Vellodi introduced **English and Telugu** as official languages in place of Urdu.\n*   Chaudhuri began appointing non-locals proficient in English for administrative work — first from Kerala, then Tamilians from Madras, and finally Telugu (Andhra) people from Madras.\n*   The stated reason was that Telangana people lacked English proficiency; this resulted in large-scale, indiscriminate appointment of Andhra personnel to Telangana jobs.\n*   The translation of Urdu-language land records into English led to widespread land-rights fraud.\n*   Many land records were destroyed, and a significant amount of land in the former Hyderabad state was effectively looted through this process.\n*   Telugu was introduced into the state education system, and teaching jobs went largely to Andhra personnel because of their proficiency in Telugu.\n\n**Bypassing the Mulki Rules:** Government appointments were held to not require compliance with Provisions **1(A)** and **1(C)** of the **1949 Mulki Regulations** issued by the civil government under Vellodi''s administration:\n\n*   **1(A)**: Mulki means a person native by birth.\n*   **1(C)**: The father must have completed 15 years of government service by the time of the person''s birth.\n\nBy exempting appointments from these provisions, the Vellodi government effectively undermined mulki protections.\n\n*   Vellodi appointed Andhra officers as chief administrators, ranking above district collectors of the erstwhile Hyderabad state.\n*   He even appointed the Tahsildar of Krishna district, **Ramachandra Rao**, as chief administrator for Hyderabad district.\n*   These Andhra officers, in turn, brought in relatives and friends from their home region for jobs, fostering favouritism and bribery.\n*   **Padmaja Naidu** raised the issue of corruption in Parliament, to which **Vallabhbhai Patel** replied that such corruption already existe' WHERE chapter_slug = 'telangana-history-en-chapter30-mulki-movement';
UPDATE theory_content SET concepts_json = concepts_json || 'd and was not new to Hyderabad.\n*   **Gogineni Ranganayakulu**, from the Andhra region, wrote a book titled _Colonization Policy of HEH Nizam of Hyderabad_, noting that **10 lakh acres** of land in Hyderabad province were suitable for colonists.\n*   The newspaper **The Star of Hyderabad** reported repeated violations of the Mulki Rules after Hyderabad''s merger with India, and hundreds of non-mulkis entered government service during the rebuilding of the state''s administrative structure.\n*   Andhra officers who obtained jobs in this manner began to dominate and mistreat Telangana people, mocking and disparaging Telangana''s culture and language.\n\nThese developments together led to the **Gair-Mulki Movement of 1952**.", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter30-mulki-movement-p5", "partName": "Situation After Police Action: Language and Employee Grievances", "bodyMd": "After Police Action, large numbers of Union (non-local) employees came to Hyderabad.\n\n*   The shift of administrative business into English, and the growing importance of regional languages, made teachers proficient in regional-language instruction a necessity in schools.\n*   Although the mulki-certificate requirement for state employment remained on the books, mulki certificates were somehow obtained by many, regardless of what language they actually spoke.\n*   A large share of those recruited as employees and teachers held certificates in a mulki category.\n\nInitially this issue attracted little attention.\n\n*   The newly arrived employees behaved as though they were doing the \"uncivilised\" region a favour by modernising it, treating the existing population as somehow inferior.\n*   Many of these new arrivals treated their postings casually, extracted bribes freely, and did not genuinely assist the local public.\n*   Because their conduct was so poor, the already-serving local employees came to look better by comparison.\n*   Union employees who had arrived in these positions then spread deliberate, harmful propaganda against the officers already working locally, further deepening ill-feeling.\n\n**Urdu language and institutional divide:**\n\n*   Urdu, one of India''s languages, was promoted by the Nizam government to university level under British influence.\n    \n*   In principle it was just one language among the nation''s many mother tongues (Telugu, Marathi, Kannada each being the true mother tongue of most residents).\n    \n*   Even so, the state government privileged Urdu, imposing it as an alien administrative language over the people — a policy that reduced the spread of education in Andhra areas.\n    \n*   Prominent literary figures, from Rabindranath Tagore to Rajagopalachari, publicly criticised this policy.\n    \n*   It was only after a Congress government came to power in the state that Urdu''s official status was withdrawn and English was introduced in its place.\n    \n*   **Northern (non-mulki) Urdu** patrons included Dr. Abdul Haq; **Deccani (mulki) Urdu** was patronised by Acharya Peetham of Khadar Mohiuddin Zore.\n    \n*   Northern Urdu was institutionally backed by the body \"Idara Adabiyat-e-Urdu,\" while Deccani Urdu was supported by \"Anjuman Tarraqi-e-Urdu.\"\n    \n*   A translation department, **Darul Tarjuma**, was set up at Osmania University to translate reference texts, drawing on eminent local pandits, scholars, and linguists.\n    \n*   The resulting translations, of high scholarly standard, remain useful in present-day Pakistan.\n    \n*   In the historiography and academic discourse produced around Deccani Urdu''s achievements, however, it was Northern (non-mulki) Urdu that received institutional prominence.\n    \n*   Until the Police Action, official patronage and leadership positions overwhelmingly went to outsiders.\n    \n*   Once instruction at Osmania University began in Urdu, it gave the poor and ordinary people somewhat greater access to education.\n    \n*   But without matching economic means, many educated youths still could not achieve corresponding social advancement, while under-qualified jagirdars continued to occupy top positions purely by status.\n    \n*   This feudal arrangement caused hardship even for ordinary Muslims, and the resulting unrest is described as the mulki agitation''s continuation into the fourth decade (the 1940s).\n    \n\n**Restricted spread of the mulki movement:**\n\n*   The mulki movement, as it stood, was confined largely to Telangana.\n*   The erstwhile Hyderabad-state regions of **Marathwada** and **Karnataka** were not troubled by it in the same way.\n*   Those regions, over time, simply lost the distinction, so that their inhabitants became indistinguishable from later settlers, unlike in Telangana.\n\n**Popular resolutions on language in education (1941):** At the Hyderabad People''s Education Conference session, held under the presidency of **Vinayakarao Vidyalankar** in April 1941, the following resolutions were unanimously adopted:\n\n1.  Instruction up to Matriculation should be in the student''s own mother tongue.\n2.  After Matriculation, instruction in place of Urdu should be in English.\n3.  Hindi and Sanskrit should be taught as languages.\n4.  Students should be permitted to sing **Vande Mataram**.\n5.  Restrictions preventing entry into \"Khaki schools\" should be lifted.\n\nSeparately, in May 1941, **Prajamandali** president **Joshi** submitted a memorandum to the state government with these demands:\n\n1.  Instruction should be conducted in Telugu, Marathi, and Kannada.\n2.  Orders banning Khaki schools should be withdrawn.\n3.  Instruction should not be conducted in Urdu where it is unnecessary for Hindu girls.\n4.  Primary education should be made free and compulsory.\n5.  Prajamandali representatives should have a role in drafting textbooks.\n6.  Regional languages should be declared official languages in their respective regions.\n\n**Burgula Ramakrishna Rao''s 1944 address:**\n\n*   As presiding chairman of the Hyderabad Prajaa Vidya Mahasabha (People''s Education Conference), **Burgula Ramakrishna Rao** delivered a historic address from its platform on **11 November 1944**.\n*   He argued that even while accepting and implementing the principle of instruction in the mother tongue, it made no sense to continue teaching non-native-Urdu-speaking students in Urdu.\n*   He also noted that, of the schools using English as the medium of instruction in the state — a small number relative to the state''s overall population — access for Hindu children remained difficult.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter30-mulki-movement';
